163|static inline bool can_contain(cmark_node_type parent_type,
164|                               cmark_node_type child_type) {
165|  return (parent_type == CMARK_NODE_DOCUMENT ||
166|          parent_type == CMARK_NODE_BLOCK_QUOTE ||
167|          parent_type == CMARK_NODE_ITEM ||
168|          (parent_type == CMARK_NODE_LIST && child_type == CMARK_NODE_ITEM));
169|}
