542|cmark_node *cmark_parse_file(FILE *f, int options) {
543|  unsigned char buffer[4096];
544|  cmark_parser *parser = cmark_parser_new(options);
545|  size_t bytes;
546|  cmark_node *document;
547|
548|  while ((bytes = fread(buffer, 1, sizeof(buffer), f)) > 0) {
549|    bool eof = bytes < sizeof(buffer);
550|    S_parser_feed(parser, buffer, bytes, eof);
551|    if (eof) {
552|      break;
553|    }
554|  }
555|
556|  document = cmark_parser_finish(parser);
557|  cmark_parser_free(parser);
558|  return document;
559|}
