1012|  bufsize_t startpos = subj->pos;
1013|  int length = 0;
1014|  unsigned char c;
1015|
1016|  // advance past [
1017|  if (peek_char(subj) == '[') {
1018|    advance(subj);
1019|  } else {
1020|    return 0;
1021|  }
