1023|  while ((c = peek_char(subj)) && c != '[' && c != ']') {
1024|    if (c == '\\') {
1025|      advance(subj);
1026|      length++;
1027|      if (cmark_ispunct(peek_char(subj))) {
1028|        advance(subj);
