80|struct render_state {
81|  cmark_strbuf *xml;
82|  int indent;
83|};
84|
85|static inline void indent(struct render_state *state) {
86|  int i;
87|  for (i = 0; i < state->indent && i < MAX_INDENT; i++) {
88|    cmark_strbuf_putc(state->xml, ' ');
89|  }
