57|int houdini_escape_href(cmark_strbuf *ob, const uint8_t *src, bufsize_t size) {
58|  static const uint8_t hex_chars[] = "0123456789ABCDEF";
59|  bufsize_t i = 0, org;
60|  uint8_t hex_str[3];
61|
62|  hex_str[0] = '%';
63|
64|  while (i < size) {
65|    org = i;
66|    while (i < size && HREF_SAFE[src[i]] != 0)
67|      i++;
68|
69|    if (likely(i > org))
70|      cmark_strbuf_put(ob, src + org, i - org);
71|
72|    /* escaping */
73|    if (i >= size)
74|      break;
75|
76|    switch (src[i]) {
77|    /* amp appears all the time in URLs, but needs
78|     * HTML-entity escaping to be inside an href */
79|    case '&':
80|      cmark_strbuf_puts(ob, "&amp;");
81|      break;
82|
83|    /* the single quote is a valid URL character
84|     * according to the standard; it needs HTML
85|     * entity escaping too */
86|    case '\'':
87|      cmark_strbuf_puts(ob, "&#x27;");
88|      break;
89|
90|/* the space can be escaped to %20 or a plus
91| * sign. we're going with the generic escape
92| * for now. the plus thing is more commonly seen
93| * when building GET strings */
94|#if 0
95|    case ' ':
96|      cmark_strbuf_putc(ob, '+');
97|      break;
98|#endif
99|
100|    /* every other character goes with a %XX escaping */
101|    default:
102|      hex_str[1] = hex_chars[(src[i] >> 4) & 0xF];
103|      hex_str[2] = hex_chars[src[i] & 0xF];
104|      cmark_strbuf_put(ob, hex_str, 3);
105|    }
106|
107|    i++;
108|  }
109|
110|  return 1;
111|}

46|int houdini_escape_html(cmark_strbuf *ob, const uint8_t *src, bufsize_t size,
47|                         int secure) {
48|  bufsize_t i = 0, org, esc = 0;
49|
50|  while (i < size) {
51|    org = i;
52|    while (i < size && (esc = HTML_ESCAPE_TABLE[src[i]]) == 0)
53|      i++;
54|
55|    if (i > org)
56|      cmark_strbuf_put(ob, src + org, i - org);
57|
58|    /* escaping */
59|    if (unlikely(i >= size))
60|      break;
61|
62|    /* The forward slash is only escaped in secure mode */
63|    if ((src[i] == '/' || src[i] == '\'') && !secure) {
64|      cmark_strbuf_putc(ob, src[i]);
65|    } else {
66|      cmark_strbuf_puts(ob, HTML_ESCAPES[esc]);
67|    }
68|
69|    i++;
70|  }
71|
72|  return 1;
73|}

58|bufsize_t houdini_unescape_ent(cmark_strbuf *ob, const uint8_t *src,
59|                               bufsize_t size) {
60|  bufsize_t i = 0;
61|
62|  if (size >= 3 && src[0] == '#') {
63|    int codepoint = 0;
64|    int num_digits = 0;
65|    int max_digits = 7;
66|
67|    if (_isdigit(src[1])) {
68|      for (i = 1; i < size && _isdigit(src[i]); ++i) {
69|        codepoint = (codepoint * 10) + (src[i] - '0');
70|
71|        if (codepoint >= 0x110000) {
72|          // Keep counting digits but
73|          // avoid integer overflow.
74|          codepoint = 0x110000;
75|        }
76|      }
77|
78|      num_digits = i - 1;
79|      max_digits = 7;
80|    }
81|
82|    else if (src[1] == 'x' || src[1] == 'X') {
83|      for (i = 2; i < size && _isxdigit(src[i]); ++i) {
84|        codepoint = (codepoint * 16) + ((src[i] | 32) % 39 - 9);
85|
86|        if (codepoint >= 0x110000) {
87|          // Keep counting digits but
88|          // avoid integer overflow.
89|          codepoint = 0x110000;
90|        }
91|      }
92|
93|      num_digits = i - 2;
94|      max_digits = 6;
95|    }
96|
97|    if (num_digits >= 1 && num_digits <= max_digits &&
98|                    i < size && src[i] == ';') {
99|      if (codepoint == 0 || (codepoint >= 0xD800 && codepoint < 0xE000) ||
100|          codepoint >= 0x110000) {
101|        codepoint = 0xFFFD;
102|      }
103|      cmark_utf8proc_encode_char(codepoint, ob);
104|      return i + 1;
105|    }
106|  }
107|
108|  else {
109|    if (size > ENT_MAX_LENGTH)
110|      size = ENT_MAX_LENGTH;
111|
112|    for (i = ENT_MIN_LENGTH; i < size; ++i) {
113|      if (src[i] == ' ')
114|        break;
115|
116|      if (src[i] == ';') {
117|        bufsize_t size;
118|        const unsigned char *entity = S_lookup_entity(src, i, &size);
119|
120|        if (entity != NULL) {
121|          cmark_strbuf_put(ob, entity, size);
122|          return i + 1;
123|        }
124|
125|        break;
126|      }
127|    }
128|  }
129|
130|  return 0;
131|}

133|int houdini_unescape_html(cmark_strbuf *ob, const uint8_t *src,
134|                          bufsize_t size) {
135|  bufsize_t i = 0, org, ent;
136|
137|  while (i < size) {
138|    org = i;
139|    while (i < size && src[i] != '&')
140|      i++;
141|
142|    if (likely(i > org)) {
143|      if (unlikely(org == 0)) {
144|        if (i >= size)
145|          return 0;
146|
147|        cmark_strbuf_grow(ob, HOUDINI_UNESCAPED_SIZE(size));
148|      }
149|
150|      cmark_strbuf_put(ob, src + org, i - org);
151|    }
152|
153|    /* escaping */
154|    if (i >= size)
155|      break;
156|
157|    i++;
158|
159|    ent = houdini_unescape_ent(ob, src + i, size - i);
160|    i += ent;
161|
162|    /* not really an entity */
163|    if (ent == 0)
164|      cmark_strbuf_putc(ob, '&');
165|  }
166|
167|  return 1;
168|}

170|void houdini_unescape_html_f(cmark_strbuf *ob, const uint8_t *src,
171|                             bufsize_t size) {
172|  if (!houdini_unescape_html(ob, src, size))
173|    cmark_strbuf_put(ob, src, size);
174|}

44|static int S_render_node(cmark_node *node, cmark_event_type ev_type,
45|                         struct render_state *state, int options) {
46|  cmark_node *parent;
47|  cmark_node *grandparent;
48|  cmark_strbuf *html = state->html;
49|  char start_heading[] = "<h0";
50|  char end_heading[] = "</h0";
51|  bool tight;
52|  char buffer[BUFFER_SIZE];
53|
54|  bool entering = (ev_type == CMARK_EVENT_ENTER);
55|
56|  if (state->plain == node) { // back at original node
57|    state->plain = NULL;
58|  }
59|
60|  if (state->plain != NULL) {
61|    switch (node->type) {
62|    case CMARK_NODE_TEXT:
63|    case CMARK_NODE_CODE:
64|    case CMARK_NODE_HTML_INLINE:
65|      escape_html(html, node->data, node->len);
66|      break;
67|
68|    case CMARK_NODE_LINEBREAK:
69|    case CMARK_NODE_SOFTBREAK:
70|      cmark_strbuf_putc(html, ' ');
71|      break;
72|
73|    default:
74|      break;
75|    }
76|    return 1;
77|  }
78|
79|  switch (node->type) {
80|  case CMARK_NODE_DOCUMENT:
81|    break;
82|
83|  case CMARK_NODE_BLOCK_QUOTE:
84|    if (entering) {
85|      cr(html);
86|      cmark_strbuf_puts(html, "<blockquote");
87|      S_render_sourcepos(node, html, options);
88|      cmark_strbuf_puts(html, ">\n");
89|    } else {
90|      cr(html);
91|      cmark_strbuf_puts(html, "</blockquote>\n");
92|    }
93|    break;
94|
95|  case CMARK_NODE_LIST: {
96|    cmark_list_type list_type = (cmark_list_type)node->as.list.list_type;
97|    int start = node->as.list.start;
98|
99|    if (entering) {
100|      cr(html);
101|      if (list_type == CMARK_BULLET_LIST) {
102|        cmark_strbuf_puts(html, "<ul");
103|        S_render_sourcepos(node, html, options);
104|        cmark_strbuf_puts(html, ">\n");
105|      } else if (start == 1) {
106|        cmark_strbuf_puts(html, "<ol");
107|        S_render_sourcepos(node, html, options);
108|        cmark_strbuf_puts(html, ">\n");
109|      } else {
110|        snprintf(buffer, BUFFER_SIZE, "<ol start=\"%d\"", start);
111|        cmark_strbuf_puts(html, buffer);
112|        S_render_sourcepos(node, html, options);
113|        cmark_strbuf_puts(html, ">\n");
114|      }
115|    } else {
116|      cmark_strbuf_puts(html,
117|                        list_type == CMARK_BULLET_LIST ? "</ul>\n" : "</ol>\n");
118|    }
119|    break;
120|  }
121|
122|  case CMARK_NODE_ITEM:
123|    if (entering) {
124|      cr(html);
125|      cmark_strbuf_puts(html, "<li");
126|      S_render_sourcepos(node, html, options);
127|      cmark_strbuf_putc(html, '>');
128|    } else {
129|      cmark_strbuf_puts(html, "</li>\n");
130|    }
131|    break;
132|
133|  case CMARK_NODE_HEADING:
134|    if (entering) {
135|      cr(html);
136|      start_heading[2] = (char)('0' + node->as.heading.level);
137|      cmark_strbuf_puts(html, start_heading);
138|      S_render_sourcepos(node, html, options);
139|      cmark_strbuf_putc(html, '>');
140|    } else {
141|      end_heading[3] = (char)('0' + node->as.heading.level);
142|      cmark_strbuf_puts(html, end_heading);
143|      cmark_strbuf_puts(html, ">\n");
144|    }
145|    break;
146|
147|  case CMARK_NODE_CODE_BLOCK:
148|    cr(html);
149|
150|    if (node->as.code.info == NULL || node->as.code.info[0] == 0) {
151|      cmark_strbuf_puts(html, "<pre");
152|      S_render_sourcepos(node, html, options);
153|      cmark_strbuf_puts(html, "><code>");
154|    } else {
155|      bufsize_t first_tag = 0;
156|      while (node->as.code.info[first_tag] &&
157|             !cmark_isspace(node->as.code.info[first_tag])) {
158|        first_tag += 1;
159|      }
160|
161|      cmark_strbuf_puts(html, "<pre");
162|      S_render_sourcepos(node, html, options);
163|      cmark_strbuf_puts(html, "><code class=\"");
164|      if (strncmp((char *)node->as.code.info, "language-", 9) != 0) {
165|        cmark_strbuf_puts(html, "language-");
166|      }
167|      escape_html(html, node->as.code.info, first_tag);
168|      cmark_strbuf_puts(html, "\">");
169|    }
170|
171|    escape_html(html, node->data, node->len);
172|    cmark_strbuf_puts(html, "</code></pre>\n");
173|    break;
174|
175|  case CMARK_NODE_HTML_BLOCK:
176|    cr(html);
177|    if (!(options & CMARK_OPT_UNSAFE)) {
178|      cmark_strbuf_puts(html, "<!-- raw HTML omitted -->");
179|    } else {
180|      cmark_strbuf_put(html, node->data, node->len);
181|    }
182|    cr(html);
183|    break;
184|
185|  case CMARK_NODE_CUSTOM_BLOCK: {
186|    unsigned char *block = entering ? node->as.custom.on_enter :
187|                                      node->as.custom.on_exit;
188|    cr(html);
189|    if (block) {
190|      cmark_strbuf_puts(html, (char *)block);
191|    }
192|    cr(html);
193|    break;
194|  }
195|
196|  case CMARK_NODE_THEMATIC_BREAK:
197|    cr(html);
198|    cmark_strbuf_puts(html, "<hr");
199|    S_render_sourcepos(node, html, options);
200|    cmark_strbuf_puts(html, " />\n");
201|    break;
202|
203|  case CMARK_NODE_PARAGRAPH:
204|    parent = cmark_node_parent(node);
205|    grandparent = cmark_node_parent(parent);
206|    if (grandparent != NULL && grandparent->type == CMARK_NODE_LIST) {
207|      tight = grandparent->as.list.tight;
208|    } else {
209|      tight = false;
210|    }
211|    if (!tight) {
212|      if (entering) {
213|        cr(html);
214|        cmark_strbuf_puts(html, "<p");
215|        S_render_sourcepos(node, html, options);
216|        cmark_strbuf_putc(html, '>');
217|      } else {
218|        cmark_strbuf_puts(html, "</p>\n");
219|      }
220|    }
221|    break;
222|
223|  case CMARK_NODE_TEXT:
224|    escape_html(html, node->data, node->len);
225|    break;
226|
227|  case CMARK_NODE_LINEBREAK:
228|    cmark_strbuf_puts(html, "<br />\n");
229|    break;
230|
231|  case CMARK_NODE_SOFTBREAK:
232|    if (options & CMARK_OPT_HARDBREAKS) {
233|      cmark_strbuf_puts(html, "<br />\n");
234|    } else if (options & CMARK_OPT_NOBREAKS) {
235|      cmark_strbuf_putc(html, ' ');
236|    } else {
237|      cmark_strbuf_putc(html, '\n');
238|    }
239|    break;
240|
241|  case CMARK_NODE_CODE:
242|    cmark_strbuf_puts(html, "<code>");
243|    escape_html(html, node->data, node->len);
244|    cmark_strbuf_puts(html, "</code>");
245|    break;
246|
247|  case CMARK_NODE_HTML_INLINE:
248|    if (!(options & CMARK_OPT_UNSAFE)) {
249|      cmark_strbuf_puts(html, "<!-- raw HTML omitted -->");
250|    } else {
251|      cmark_strbuf_put(html, node->data, node->len);
252|    }
253|    break;
254|
255|  case CMARK_NODE_CUSTOM_INLINE: {
256|    unsigned char *block = entering ? node->as.custom.on_enter :
257|                                      node->as.custom.on_exit;
258|    if (block) {
259|      cmark_strbuf_puts(html, (char *)block);
260|    }
261|    break;
262|  }
263|
264|  case CMARK_NODE_STRONG:
265|    if (entering) {
266|      cmark_strbuf_puts(html, "<strong>");
267|    } else {
268|      cmark_strbuf_puts(html, "</strong>");
269|    }
270|    break;
271|
272|  case CMARK_NODE_EMPH:
273|    if (entering) {
274|      cmark_strbuf_puts(html, "<em>");
275|    } else {
276|      cmark_strbuf_puts(html, "</em>");
277|    }
278|    break;
279|
280|  case CMARK_NODE_LINK:
281|    if (entering) {
282|      cmark_strbuf_puts(html, "<a href=\"");
283|      if (node->as.link.url && ((options & CMARK_OPT_UNSAFE) ||
284|                                !(_scan_dangerous_url(node->as.link.url)))) {
285|        houdini_escape_href(html, node->as.link.url,
286|                            (bufsize_t)strlen((char *)node->as.link.url));
287|      }
288|      if (node->as.link.title) {
289|        cmark_strbuf_puts(html, "\" title=\"");
290|        escape_html(html, node->as.link.title,
291|                    (bufsize_t)strlen((char *)node->as.link.title));
292|      }
293|      cmark_strbuf_puts(html, "\">");
294|    } else {
295|      cmark_strbuf_puts(html, "</a>");
296|    }
297|    break;
298|
299|  case CMARK_NODE_IMAGE:
300|    if (entering) {
301|      cmark_strbuf_puts(html, "<img src=\"");
302|      if (node->as.link.url && ((options & CMARK_OPT_UNSAFE) ||
303|                                !(_scan_dangerous_url(node->as.link.url)))) {
304|        houdini_escape_href(html, node->as.link.url,
305|                            (bufsize_t)strlen((char *)node->as.link.url));
306|      }
307|      cmark_strbuf_puts(html, "\" alt=\"");
308|      state->plain = node;
309|    } else {
310|      if (node->as.link.title) {
311|        cmark_strbuf_puts(html, "\" title=\"");
312|        escape_html(html, node->as.link.title,
313|                    (bufsize_t)strlen((char *)node->as.link.title));
314|      }
315|
316|      cmark_strbuf_puts(html, "\" />");
317|    }
318|    break;
319|
320|  default:
321|    assert(false);
322|    break;
323|  }
324|
325|  // cmark_strbuf_putc(html, 'x');
326|  return 1;
327|}

251|static bufsize_t cmark_set_cstr(cmark_mem *mem, unsigned char **dst,
252|                                const char *src) {
253|  unsigned char *old = *dst;
254|  bufsize_t len;
255|
256|  if (src && src[0]) {
257|      len = (bufsize_t)strlen(src);
258|      *dst = (unsigned char *)mem->realloc(NULL, len + 1);
259|      memcpy(*dst, src, len + 1);
260|  } else {
261|      len = 0;
262|      *dst = NULL;
263|  }
264|  if (old) {
265|    mem->free(old);
266|  }
267|
268|  return len;
269|}

21|static void S_out(cmark_renderer *renderer, const char *source, bool wrap,
22|                  cmark_escaping escape) {
23|  int length = (int)strlen(source);
24|  unsigned char nextc;
25|  int32_t c;
26|  int i = 0;
27|  int last_nonspace;
28|  int len;
29|  int k = renderer->buffer->size - 1;
30|
31|  wrap = wrap && !renderer->no_linebreaks;
32|
33|  if (renderer->in_tight_list_item && renderer->need_cr > 1) {
34|    renderer->need_cr = 1;
35|  }
36|  while (renderer->need_cr) {
37|    if (k < 0 || renderer->buffer->ptr[k] == '\n') {
38|      k -= 1;
39|    } else {
40|      cmark_strbuf_putc(renderer->buffer, '\n');
41|      if (renderer->need_cr > 1) {
42|        cmark_strbuf_put(renderer->buffer, renderer->prefix->ptr,
43|                         renderer->prefix->size);
44|      }
45|    }
46|    renderer->column = 0;
47|    renderer->last_breakable = 0;
48|    renderer->begin_line = true;
49|    renderer->begin_content = true;
50|    renderer->need_cr -= 1;
51|  }
52|
53|  while (i < length) {
54|    if (renderer->begin_line) {
55|      cmark_strbuf_put(renderer->buffer, renderer->prefix->ptr,
56|                       renderer->prefix->size);
57|      // note: this assumes prefix is ascii:
58|      renderer->column = renderer->prefix->size;
59|    }
60|
61|    len = cmark_utf8proc_iterate((const uint8_t *)source + i, length - i, &c);
62|    if (len == -1) { // error condition
63|      return;        // return without rendering rest of string
64|    }
65|    nextc = source[i + len];
66|    if (c == 32 && wrap) {
67|      if (!renderer->begin_line) {
68|        last_nonspace = renderer->buffer->size;
69|        cmark_strbuf_putc(renderer->buffer, ' ');
70|        renderer->column += 1;
71|        renderer->begin_line = false;
72|        renderer->begin_content = false;
73|        // skip following spaces
74|        while (source[i + 1] == ' ') {
75|          i++;
76|        }
77|        // We don't allow breaks that make a digit the first character
78|        // because this causes problems with commonmark output.
79|        if (!cmark_isdigit(source[i + 1])) {
80|          renderer->last_breakable = last_nonspace;
81|        }
82|      }
83|
84|    } else if (escape == LITERAL) {
85|      if (c == 10) {
86|        cmark_strbuf_putc(renderer->buffer, '\n');
87|        renderer->column = 0;
88|        renderer->begin_line = true;
89|        renderer->begin_content = true;
90|        renderer->last_breakable = 0;
91|      } else {
92|        cmark_render_code_point(renderer, c);
93|        renderer->begin_line = false;
94|        // we don't set 'begin_content' to false til we've
95|        // finished parsing a digit.  Reason:  in commonmark
96|        // we need to escape a potential list marker after
97|        // a digit:
98|        renderer->begin_content =
99|            renderer->begin_content && cmark_isdigit(c) == 1;
100|      }
101|    } else {
102|      (renderer->outc)(renderer, escape, c, nextc);
103|      renderer->begin_line = false;
104|      renderer->begin_content =
105|          renderer->begin_content && cmark_isdigit(c) == 1;
106|    }
107|
108|    // If adding the character went beyond width, look for an
109|    // earlier place where the line could be broken:
110|    if (renderer->width > 0 && renderer->column > renderer->width &&
111|        !renderer->begin_line && renderer->last_breakable > 0) {
112|
113|      // copy from last_breakable to remainder
114|      unsigned char *src = renderer->buffer->ptr +
115|                           renderer->last_breakable + 1;
116|      bufsize_t remainder_len = renderer->buffer->size -
117|                                renderer->last_breakable - 1;
118|      unsigned char *remainder =
119|          (unsigned char *)renderer->mem->realloc(NULL, remainder_len);
120|      memcpy(remainder, src, remainder_len);
121|      // truncate at last_breakable
122|      cmark_strbuf_truncate(renderer->buffer, renderer->last_breakable);
123|      // add newline, prefix, and remainder
124|      cmark_strbuf_putc(renderer->buffer, '\n');
125|      cmark_strbuf_put(renderer->buffer, renderer->prefix->ptr,
126|                       renderer->prefix->size);
127|      cmark_strbuf_put(renderer->buffer, remainder, remainder_len);
128|      renderer->column = renderer->prefix->size + remainder_len;
129|      renderer->mem->free(remainder);
130|      renderer->last_breakable = 0;
131|      renderer->begin_line = false;
132|      renderer->begin_content = false;
133|    }
134|
135|    i += len;
136|  }
137|}

